#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Reproduce the fixed-point WT voice filter and LFO lookup data, without dependencies."""
import argparse
import math
from pathlib import Path

OUTPUT = Path(__file__).resolve().parents[1] / "firmware" / "src" / "wt_dsp_data.h"


def generate():
    cutoffs = [min(20000, 20 * 800**(c / 128)) for c in range(134)]
    lines = [
        "/* SPDX-License-Identifier: GPL-3.0-only",
        " * Generated by tools/gen_wt_dsp.py; do not edit.",
        " * TPT state-variable filter: legacy 129 cutoffs (20..16000 Hz), five extra knots to 20000 Hz.",
        " * 16 logarithmic Q settings (sqrt(0.5)..8), coefficients in Q30.",
        " */",
        "#ifndef WT_DSP_DATA_H", "#define WT_DSP_DATA_H",
        "#define WT_FILTER_STEPS 133u",
        "static const int32_t WT_FILTER_K[16] = {",
        "    " + ", ".join(str(round(2**30 / (math.sqrt(0.5) * (8 / math.sqrt(0.5))**(r / 15))))
                         for r in range(16)),
        "};",
        "static const int32_t WT_FILTER_HZ[134] = {",
        "    " + ", ".join(str(round(f)) for f in cutoffs),
        "};",
        "static const int32_t WT_FILTER_LT[134] = {",
        "    " + ", ".join(str(round(math.log2(math.tan(math.pi*f/44100))*4096)) for f in cutoffs),
        "};",
        "static const uint32_t WT_FILTER_EXP2[17] = {",
        "    " + ", ".join(str(round(65536*2**(i/16))) for i in range(17)),
        "};",
        "static const int32_t WT_FILTER_A[16][134][3] = {",
    ]
    for r in range(16):
        k = 1 / (math.sqrt(0.5) * (8 / math.sqrt(0.5))**(r / 15))
        lines.append("    {")
        for f in cutoffs:
            g = math.tan(math.pi * f / 44100)
            a1 = 1 / (1 + g * (g + k))
            lines.append("        {" + ", ".join(str(round(x * 2**30)) for x in (a1, g*a1, g*g*a1)) + "},")
        lines.append("    },")
    lines += ["};", "static const int16_t WT_LFO_SIN[257] = {"]
    values = [round(32767 * math.sin(2 * math.pi * i / 256)) for i in range(257)]
    for i in range(0, len(values), 16):
        lines.append("    " + ", ".join(map(str, values[i:i+16])) + ",")
    lines += ["};", "#endif", ""]
    return "\n".join(lines).encode("ascii")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    data = generate()
    if args.check:
        if not OUTPUT.is_file() or OUTPUT.read_bytes() != data:
            parser.exit(1, "WT DSP data is missing or stale; run tools/gen_wt_dsp.py\n")
        print("WT DSP data: reproducible")
    else:
        OUTPUT.write_bytes(data)
        print(f"wrote {OUTPUT}")


if __name__ == "__main__":
    main()
